def f(A):
    H,W=len(A),len(A[0])
    bg=Counter(v for r in A for v in r).most_common(1)[0][0]
    # separator line: uniform row/col whose value != dominant bg? Use most common as bg candidate.
    def sep_line(cells,val): return len(set(cells))==1 and cells[0]!=val
    srow=[i for i in range(H) if sep_line(A[i],bg)]
    scol=[j for j in range(W) if sep_line([A[i][j] for i in range(H)],bg)]
    def split(lines, dim):
        # lines sorted list, gaps -> segments
        segs=[]; start=None
        for l in lines+[None]:
            if l is None:
                if start is not None: segs.append((start,l-1)); start=None
            elif (l-start)>2: pass
            else:
                if start is not None: segs.append((start,l-1)); start=None
            start=l
        if start is not None: segs.append((start,len(lines)-1))
        return segs
    # use periods: distance between consecutive separator lines
    pr = max(1, srow[-1]-srow[0]) if srow else W
    pc = max(1, scol[-1]-scol[0]) if scol else H
    out=[[bg]*W for _ in range(H)]
    # each separator-free cell belongs to a segment; copy its block onto all congruent positions
    for (r0,r1) in split(srow,'r'):
        for (c0,c1) in split(scol,'c'):
            blk=A[r0:r1+1][c0:c1+1]
            rseg=len(range(r0,r1+1)); cseg=len(range(c0,c1+1))
            for i in range(H):
                rr=i-(srow[0] if srow else 0)
                # offset modulo period, align so that block's first row maps to first row after a separator
                off_r=(i-r0)%pr if r0>=min(srow) else i%c(pr or W)
                ooo=(i%pr+r0) if False else None
            # cleaner: place block at positions where (pos - block_first) % period == 0
            base_r=r0; base_c=c0
            for i in range(H):
                if (i-base_r)%pr==0 and i-r0<rseg:
                    for j in range(W):
                        if (j-base_c)%pc==0 and j-c0<cseg:
                            out[i][j]=blk[i-r0][j-c0]
    return out

