    for a in range(len(rblock)):
        for b in range(a+1,len(rblock)):
            sa,ea,ca=rblock[a]; sb,eb,cb=rblock[b]
            if ca==cb and eb+2<sb and sa+ea-heights[a]>0:
                cand.append(sb-sa)
    Ps=set(cand)
    if not Ps: return A  # no repetition -> no op
    P=min(Ps)
    # horizontal analog
    hc=[[A[i][j] for i in range(H)] for j in range(W)]
    cblock=[]; st=None
    for j in range(W):
        if any(hc[i][j]!=bg for i in range(H)):
            if st is None: st=j
        else:
            if st is not None:
                cblock.append((st,j-1,tuple(hc[i][st:i+1] for i in range(st,min(H,st+H)))) )
                st=None
    if st is not None: cblock.append((st,W-1,tuple(hc[i][st:min(H,st+H)] for i in range(st,min(H,st+H)))))
    cands=[]
    for a in range(len(cblock)):
        for b in range(a+1,len(cblock)):
            sa,sb=cblock[a][:2],cblock[b][:2]
            if cblock[a][2]==cblock[b][2] and sb[1]-sa[1]>=1:
                cands.append(sb[1]-sa[1])
    Qs=set(cands) if cands else {W}
    if not Qs: Qs={W}
    Q=min(Qs)
    # build f over window rows [r0,r0+P-1], cols [c0,c0+Q-1]
    r0=sr=rblock[0][0] if rblock else 0
    c0=sc=cblock[0][0] if cblock else 0
    win=[[A[r0+p][c0+q] for q in range(min(Q,W))] for p in range(min(P,H))]
    def f(p,q):
        if p<0 or p>=P or q<0 or q>=Q: return bg
        return win[p%P][q%Q]
    out=[[f((r-r0)%P,(c-c0)%Q) for c in range(W)] for r in range(H)]
    return out

