import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def f(A):
    H,W=len(A),len(A[0])
    bg=Counter(v for r in A for v in r).most_common(1)[0][0]
    def u(cells): return len(set(cells))==1 and cells[0]!=bg
    srow={i for i in range(H) if u(A[i])}
    scol={j for j in range(W) if u([A[i][j] for i in range(H)])}
    nz=[(i,j) for i in range(H) for j in range(W) if A[i][j]!=bg and i not in srow and j not in scol]
    if not nz: return A
    br=min(i for i,_ in nz); bc=min(j for _,j in nz)
    bh=max(i for i,_ in nz)-br+1; bw=max(j for _,j in nz)-bc+1
    band=[[A[br+b][bc+c] for c in range(bw)] for b in range(bh)]
    sepR = next(iter(srow)) if srow else None
    sepC = next(iter(scol)) if scol else None
    if sepR is not None:
        band.append(list(A[sepR]))
    if sepC is not None:
        band=[row+[A[br+i][sepC]] for row in band]  # use tile's own rows, extended by sep col value
    P=len(band); Q=len(band[0])
    return [[band[r%P][c%Q] for c in range(W)] for r in range(H)]

